def format_parameter_help(name: str, current: str) -> str:
    label, meaning, default, recommended, smaller, larger, note, first = PARAMETER_HELP[name]
    return (f"{label}\n\n현재 값: {current}\n기본값: {default}\n권장 범위: {recommended}\n"
            f"의미: {meaning}\n값을 낮추면: {smaller}\n값을 높이면: {larger}\n"
            f"현재 실험에서의 의미: {note}\n추천 실험값: {first}")
